-- Versioned private local candidate. No old rows, migrations, locks or protocol identities are rewritten.
LOCK TABLE qf.quizpack_import,qf.quizpack_validation,qf.product_asset,qf.draft_revision,qf.product_version,qf.internal_play_version,qf.access_key,qf.consumer_session,qf.consumer_grant,qf.quiz_report IN SHARE ROW EXCLUSIVE MODE NOWAIT;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND usename=replace(current_user,'qf_owner_','qf_app_') AND pid<>pg_backend_pid()) THEN RAISE EXCEPTION 'D3_WRITERS_PRESENT' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT 1 FROM qf.quizpack_import WHERE status='receiving' OR storage_condition<>'clean' OR reserved_bytes<>0 OR lease_until IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(attempts) a WHERE a->>'disposition'<>'released'))
 OR EXISTS(SELECT 1 FROM qf.quizpack_validation WHERE status IN ('validating','archiving') OR storage_condition<>'clean' OR reserved_bytes<>0 OR lease_until IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(attempts_text::jsonb) a WHERE a->>'disposition'<>'released' OR a->>'mediaStop'='unconfirmed'))
 THEN RAISE EXCEPTION 'D3_UNSETTLED_IO' USING ERRCODE='55000'; END IF;
END $$;

DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.consumer_schema_v2(text)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='0bc4dfa5965dcc9098ec4dd8426607137e8af67ad8710c7cfff870ae24ca8815') THEN RAISE EXCEPTION 'PRIVATE_TEST_PREVIOUS_HELPER_CHANGED'; END IF; END $$;
