DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.internal_review_valid(qf.draft_review)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='a73ddda1378f7b35cfd9174da321450cd82b0daef5e1a71b1d4521f25105aa16') THEN RAISE EXCEPTION 'PRIVATE_TEST_PREVIOUS_HELPER_CHANGED'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.protect_internal_reference()'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='ad4b4b98ec64dead58b94b949e0e6a9dec36f3fecf6fd60b25243bc46697e2ee') THEN RAISE EXCEPTION 'PRIVATE_TEST_PREVIOUS_HELPER_CHANGED'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.validation_shape_valid(qf.quizpack_validation)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='d0a5b66fc074930440a47903d55e30d78c1c6819c082034cb904cccdfe880f0a') THEN RAISE EXCEPTION 'PRIVATE_TEST_PREVIOUS_HELPER_CHANGED'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.protect_product_asset()'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='f8902af1e2c8280e79e335e9c1a68a7819cc39f837387f564d671f0d58d417b6') THEN RAISE EXCEPTION 'PRIVATE_TEST_PREVIOUS_HELPER_CHANGED'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.protect_consumer_report()'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='0323cf661cfdaa6755f8d745c9b258d7d5326db4d528366efe0141ba62ed079d') THEN RAISE EXCEPTION 'PRIVATE_TEST_PREVIOUS_HELPER_CHANGED'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='qf.consumer_report_valid(qf.quiz_report)'::regprocedure AND encode(sha256(convert_to(prosrc,'UTF8')),'hex')='da4c11639188deb9dcfcb6fa5cbacb3d54b7f1411d5d98d25918e12da5d5f8f1') THEN RAISE EXCEPTION 'PRIVATE_TEST_PREVIOUS_HELPER_CHANGED'; END IF; END $$;

CREATE FUNCTION qf.private_test_database_valid() RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT current_database()='qf_db_953991305a7e8c49bb773d95cd120378' AND shobj_description((SELECT oid FROM pg_database WHERE datname=current_database()),'pg_database')='quizforge.p2a.v1:953991305a7e8c49bb773d95cd120378:test' $$;
CREATE FUNCTION qf.private_test_structure_valid(source jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE marked boolean; private_count integer; total integer;
BEGIN
 marked:=(source->'bindings') ? 'privateTestUse';
 SELECT count(*)::integer,count(*) FILTER(WHERE r->>'approval'='private-test-only')::integer INTO total,private_count FROM jsonb_array_elements(source#>'{bindings,resources}') r;
 IF NOT marked THEN RETURN private_count=0; END IF;
 RETURN (total>0 AND total=private_count AND source#>>'{bindings,kind}'='authored'
  AND source#>'{bindings,privateTestUse}'='{"authorizationId":"qztx-full-flow-20261030","contentStatus":"candidate","instanceId":"953991305a7e8c49bb773d95cd120378","resourceStatus":"reference-or-candidate","schemaVersion":"quizforge.private-test-use.v1"}'::jsonb
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source#>'{bindings,resources}') r WHERE r#>'{license,commercialUse}' IS DISTINCT FROM 'false'::jsonb OR r#>'{license,redistribution}' IS DISTINCT FROM 'false'::jsonb OR r#>>'{license,scope}' IS DISTINCT FROM 'private-test-only')) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE FUNCTION qf.private_test_source_valid(source jsonb,asset_sha text,manifest_sha text) RETURNS boolean LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 IF NOT ((source->'bindings') ? 'privateTestUse') THEN RETURN true; END IF;
 RETURN (qf.private_test_database_valid() AND qf.private_test_structure_valid(source)
 AND qf.sha256_utf8(qf.consumer_canonical(source))='112c9da91f0346f780b050e340d820d20c19a144695b94c48a86a53c91040633' AND asset_sha='da03e7f4af5e621a714ec93ce7368a7f594d5f97de9b4a8534b586abf5a405a3' AND manifest_sha='351ebfcd1dd17036fceb896f0a9a50e419b628fe1260d87dd37db59cf0de5fb5') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

