tern":"^[\\s\\S]{1,240}(?![\\s\\S])"}]}},"required":["resourceRef","alt"],"additionalProperties":false}}},"required":["coverSceneRef","sections","questionFrames","resourceDescriptions"],"additionalProperties":false}},"required":["schemaVersion","kind","visualVersion","resourceVersion","componentVersion","witnesses","reportVersion","reportTemplates","resultReports","slots","resources","layouts","visualPresentation"],"additionalProperties":false}},"required":["schemaVersion","core","bindings"],"additionalProperties":false}$qztx_schema$::jsonb
