CREATE OR REPLACE FUNCTION qf.consumer_body_valid_v2(t text,kind text,maximum integer) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE v jsonb;
BEGIN
 IF octet_length(t)<2 OR octet_length(t)>maximum THEN RETURN false; END IF;
 v:=t::jsonb;
 IF kind='content' AND qf.private_test_structure_valid(v) IS NOT TRUE THEN RETURN false; END IF;
 RETURN (qf.consumer_json_valid_v2(v,qf.consumer_schema_v2(kind),0) AND t=qf.consumer_canonical(v)) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.product_asset_declaration_valid(pid text, rid text, ver text, sha text, purpose text, declaration text) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE d jsonb; b qf.asset_blob;
BEGIN
 IF declaration IS NULL OR octet_length(declaration) NOT BETWEEN 2 AND 65536 THEN RETURN false; END IF;
 d:=declaration::jsonb; SELECT * INTO b FROM qf.asset_blob WHERE sha256=sha;
 RETURN (jsonb_typeof(d)='object' AND d->>'id'=rid AND d->>'productId'=pid AND d->>'version'=ver AND d->>'sha256'=sha AND d->>'purpose'=purpose
  AND d->'bytes'=to_jsonb(b.bytes) AND d->>'mediaType'=b.media_type AND d->'width'=to_jsonb(b.width) AND d->'height'=to_jsonb(b.height) AND b.frames=1
  AND ((d#>'{license,commercialUse}'='true'::jsonb AND d#>'{license,redistribution}'='true'::jsonb AND d->>'approval' IN ('pending','approved')) OR (qf.private_test_database_valid() AND d->>'approval'='private-test-only' AND d#>'{license,commercialUse}'='false'::jsonb AND d#>'{license,redistribution}'='false'::jsonb AND d#>>'{license,scope}'='private-test-only' AND qf.sha256_utf8(qf.consumer_canonical(d)) IN ('737b559d62fda0d3e1e6be5517fc504b8a301f0b91210a07fe710e9fbeea6ba4','dd268320e2217da78246d911083314e630f9594972a8515ebf2b1986b9a0004c','2175d10d86c24ebfd3bf30a8cffdc489a96fef05415e80cb67297cc9536055f7','812c4257b8261adcc84fd162fe37b8e8c5b021ff4fc128643f7c11703938f2b2','52fec226547b407902310c3cc9367787edeb18763b145be82f504d12c5512f23','3a7952e93a23c09128e3f5184ba59fc0aaaaefbb2cdca9617079fee68eba2897','edad554862fc93f9f628b2445a0fe5eb5807a47727edd67e38b8e806e4eba771','1bd77cb75749d026620fffc21b71cbf413647b92370d5ee5f809b8a088ae4626','8516c619c7777c03152f4ab07a767f199cbdf90bf4d9f5f56763848248b2c10b','4f2d591976f94868c36fd1f50efecc2f138815364b03b22f8bd54c33af0a114b','3c91fa57072914ec3bb44ea4341c5c7f7a956691c6b31e450ff0c2690ec8c870','aaba59ea8756f64c0c69575fc376250c720ed92280abb476b5a11f58ff7992e7','b795f93147da5b1680af73c848118666a499f43fa49e3c8d114de53ecfdbf04d','e976b7944b2abfd6787c05ad4e7ea8f6a4ac17c6faa5d6230c7a303950b206b6','d1ae74a9df545b877d34da3a5890932eff635438e79b0936c3cc3f8bf862f5a6','4506dab0aea7d42582d05a9fe60ed92e4668587c10ed8dc8558500eb59c2db8c','49d96616a7cfe9f4387beb45866cf3dabe4832fa6f436e3381b7c007b9e7edb0','43e328b8ef3472f01afc5778ecfb512ae38e2e5bfaf1383a450e111cc1233508','2db57f984db51dd6491bb28c7c6badaf7e4d8d208f8bd3ca803fcf710c45ac0a','90248e7673c7ce983e23d7aa2ff91d4b6bc31d9d241773d464d94641427581f7','0a7fcd8e00102ce7a19bb7c7bd1a4763a93ec6078ce3d0ec9ca955209fc7c412','b92fdd93f0b21740b48dd29e62bd98e9c78bf14a441fc9735eb6b4d6235bfeed','4d2c5feee0c1e1d39d7af874172b987fc1893650bc85a30ead0b50da368cc72c','f90db0d215559b6f0955a93039486d3f03cbe784bddffcb9f486444738a0aea5','01997ba2538aeb4beb69f535af9b8d4e7982284e162c07f10cf7f3274324d6c2')))) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.internal_review_valid(r qf.draft_review) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE b jsonb; f jsonb; t jsonb; a jsonb;
BEGIN
 b:=r.binding_text::jsonb; f:=r.facts_text::jsonb; a:=f->'approval';
 t:=jsonb_build_object('draftId',r.draft_id,'revision',r.revision,'canonicalContentSha256',r.canonical_content_sha256::text,'assetSetSha256',r.asset_set_sha256::text,'canonicalManifestSha256',r.canonical_manifest_sha256::text);
 RETURN (r.binding_text=qf.internal_canonical(b) AND r.fingerprint::text=qf.sha256_utf8(r.binding_text)
 AND b=jsonb_build_object('schemaVersion','quizforge.review-record.v1','productId',r.product_id,'idempotencyKey',r.idempotency_key,'target',t,'baseline',b->'baseline')
 AND qf.internal_registry_identity(b->'baseline','baseline')
 AND r.facts_text=qf.internal_canonical(f) AND r.review_sha256::text=qf.sha256_utf8(r.facts_text)
 AND f=jsonb_build_object('schemaVersion','quizforge.internal-review-facts.v1','productId',r.product_id,'target',t,'baseline',b->'baseline','purpose',r.purpose,'approval',a)
 AND ((a='{"authorizationId":"qztx-full-flow-20261030","evidenceSha256":"5c321443c5931ce5622bb8bab0741366e9897c08672abeefb26363be8a86e0fb","instanceId":"953991305a7e8c49bb773d95cd120378","kind":"private-test-only","scope":"candidate-content-reference-art-local-test-only"}'::jsonb AND r.canonical_content_sha256::text='112c9da91f0346f780b050e340d820d20c19a144695b94c48a86a53c91040633' AND r.asset_set_sha256::text='da03e7f4af5e621a714ec93ce7368a7f594d5f97de9b4a8534b586abf5a405a3' AND r.canonical_manifest_sha256::text='351ebfcd1dd17036fceb896f0a9a50e419b628fe1260d87dd37db59cf0de5fb5') OR (a->>'kind'='author-baseline' AND a=jsonb_build_object('kind','author-baseline','approvedOn',a->'approvedOn','sourceRecordId',a->'sourceRecordId','evidenceSha256',a->'evidenceSha256','scope','internal-test-content-and-visual-baseline') AND a->>'approvedOn' ~ '^\d{4}-\d{2}-\d{2}$' AND a->>'sourceRecordId' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$')
 OR (a->>'kind'='synthetic-test' AND a=jsonb_build_object('kind','synthetic-test','fixtureId',a->'fixtureId','evidenceSha256',a->'evidenceSha256','scope','test-evidence-no-author-approval') AND a->>'fixtureId' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'))
 AND a->>'evidenceSha256' ~ '^[a-f0-9]{64}$') IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.validation_shape_valid(v qf.quizpack_validation) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE ident jsonb; man jsonb; content jsonb; aset jsonb; item jsonb; declaration jsonb; evidence jsonb; accepted jsonb; seen text[]:='{}'; prior_id text:=NULL; prior_version text:=NULL; key_text text; current_policy boolean; newest_policy boolean; component_version text; state_name text; component_id text;
BEGIN
 ident:=v.identity_text::jsonb;
 newest_policy:=v.archive_policy_version='quizpack-private-archive.v4';
 current_policy:=v.archive_policy_version IN ('quizpack-private-archive.v3','quizpack-private-archive.v4');
 IF v.archive_policy_version NOT IN ('quizpack-private-archive.v1','quizpack-private-archive.v2','quizpack-private-archive.v3','quizpack-private-archive.v4') THEN RETURN false; END IF;
 IF (jsonb_typeof(ident)='object' AND (SELECT count(*) FROM jsonb_object_keys(ident))=12
  AND ident ?& ARRAY['schemaVersion','validatorVersion','policyId','validatorBundleSha256','compatibilityPolicyHash','effectiveLimitsHash','persistencePolicyVersion','persistencePolicyHash','reportSchemaVersion','reportSchemaHash','runtime','identitySha256']
  AND ident->>'validatorVersion' ~ '^[!-~]{1,64}$' AND ident->>'policyId' ~ '^[!-~]{1,64}$'
  AND ident->>'persistencePolicyVersion' ~ '^[!-~]{1,64}$' AND ident->>'reportSchemaVersion' ~ '^[!-~]{1,64}$'
  AND ident->>'compatibilityPolicyHash' ~ '^[0-9a-f]{64}$' AND ident->>'effectiveLimitsHash' ~ '^[0-9a-f]{64}$'
  AND ident->>'persistencePolicyHash' ~ '^[0-9a-f]{64}$' AND ident->>'reportSchemaHash' ~ '^[0-9a-f]{64}$'
  AND jsonb_typeof(ident->'runtime')='object' AND (SELECT count(*) FROM jsonb_object_keys(ident->'runtime'))=6
  AND ident->'runtime' ?& ARRAY['schema','platform','componentId','deploymentId','runtimeBundleHash','limitsHash']
  AND ident#>>'{runtime,schema}'='quizpack-media-runtime-binding.v1' AND ident#>>'{runtime,platform}' IN ('darwin-arm64','linux-x64')
  AND ident#>>'{runtime,componentId}' ~ '^[0-9a-f]{64}$' AND ident#>>'{runtime,deploymentId}' ~ '^[0-9a-f]{64}$'
  AND ident#>>'{runtime,limitsHash}' ~ '^[0-9a-f]{64}$' AND ident->>'schemaVersion'=CASE WHEN newest_policy THEN 'quizpack-validation-identity.v3' WHEN current_policy THEN 'quizpack-validation-identity.v2' ELSE 'quizpack-validation-identity.v1' END AND ident->>'identitySha256'=v.identity_sha256 AND ident->>'validatorBundleSha256' ~ '^[0-9a-f]{64}$'
  AND ident#>>'{runtime,runtimeBundleHash}'=ident->>'validatorBundleSha256' AND v.archive_policy_version ~ '^[!-~]{1,64}$') IS NOT TRUE THEN RETURN false; END IF;
 IF current_policy THEN
  IF EXISTS(SELECT 1 FROM jsonb_each(ident) e WHERE e.key<>'runtime' AND jsonb_typeof(e.value)<>'string')
    OR EXISTS(SELECT 1 FROM jsonb_each(ident->'runtime') e WHERE jsonb_typeof(e.value)<>'string') THEN RETURN false; END IF;
  IF (v.archive_policy_sha256=CASE WHEN newest_policy THEN 'd38b04bada0b997362040b0a5440e3f7498aacb4253f7e14b8ea9b6bcdac9c29' ELSE 'a330bf3d82ada4bba47a395655347ad94b20ec3c00ffbde3f52a06773d3511d5' END
   AND ident->>'validatorVersion'=CASE WHEN newest_policy THEN '3.0.0' ELSE '2.0.0' END AND ident->>'policyId'=CASE WHEN newest_policy THEN 'quizpack-local-supported.v2' ELSE 'quizpack-local-supported.v1' END
   AND ident->>'reportSchemaVersion'=CASE WHEN newest_policy THEN 'quizpack-validation.v3' ELSE 'quizpack-validation.v2' END AND ident->>'reportSchemaHash'=CASE WHEN newest_policy THEN '8e3a916593da4316fa0e5866d192f192d1aa4b5af16c99a9393e6620e2e0d46f' ELSE 'e7df48c0d4da4e941fa1486906b08104f5fc96b9c1a001e9489fa2eedf461867' END
   AND ident->>'compatibilityPolicyHash'=CASE WHEN newest_policy THEN '9bd2826c37ec638b69e476e171afaabe3e2921c06c59ec385aea94f19a08b146' ELSE 'a1366418639c8eac052955dae4670cf179a7c9774c8039f66cc46f78252c2899' END AND ident->>'effectiveLimitsHash'='05b82df551f0210839778ca54b94a7278d44bdfd4b6dd4fc6b55105cf797dbdf'
   AND ident->>'persistencePolicyVersion'='quizpack-persistence-policy.v1' AND ident->>'persistencePolicyHash'='9ffd5e091f6f9183de746c42dbc462928dd0189b3eb8a689f4ceb1286d6104e2') IS NOT TRUE THEN RETURN false; END IF;
  key_text:='{'||'"compatibilityPolicyHash":'||to_json((ident)->>'compatibilityPolicyHash')::text||',"effectiveLimitsHash":'||to_json((ident)->>'effectiveLimitsHash')::text||',"persistencePolicyHash":'||to_json((ident)->>'persistencePolicyHash')::text||',"persistencePolicyVersion":'||to_json((ident)->>'persistencePolicyVersion')::text||',"policyId":'||to_json((ident)->>'policyId')::text||',"reportSchemaHash":'||to_json((ident)->>'reportSchemaHash')::text||',"reportSchemaVersion":'||to_json((ident)->>'reportSchemaVersion')::text||',"runtime":'||'{'||'"componentId":'||to_json((ident->'runtime')->>'componentId')::text||',"deploymentId":'||to_json((ident->'runtime')->>'deploymentId')::text||',"limitsHash":'||to_json((ident->'runtime')->>'limitsHash')::text||',"platform":'||to_json((ident->'runtime')->>'platform')::text||',"runtimeBundleHash":'||to_json((ident->'runtime')->>'runtimeBundleHash')::text||',"schema":'||to_json((ident->'runtime')->>'schema')::text||'}'||',"schemaVersion":'||to_json((ident)->>'schemaVersion')::text||',"validatorBundleSha256":'||to_json((ident)->>'validatorBundleSha256')::text||',"validatorVersion":'||to_json((ident)->>'validatorVersion')::text||'}';
  IF qf.sha256_utf8(key_text) IS DISTINCT FROM v.identity_sha256 THEN RETURN false; END IF;
 END IF;
 key_text:='{"archiveBytes":'||v.archive_bytes::text||',"archivePolicySha256":'||to_json(v.archive_policy_sha256::text)::text||',"archivePolicyVersion":'||to_json(v.archive_policy_version)::text||',"archiveSha256":'||to_json(v.archive_sha256::text)::text||',"identitySha256":'||to_json(v.identity_sha256::text)::text||',"importId":'||to_json(v.import_id::text)::text||',"productId":'||to_json(v.product_id)::text||',"schemaVersion":"quizpack-validation-key.v1"}';
 IF (qf.sha256_utf8(key_text)=v.validation_key) IS NOT TRUE THEN RETURN false; END IF;
 IF v.lease_until IS NOT NULL AND v.lease_until>clock_timestamp()+interval '120 seconds' THEN RETURN false; END IF;
 IF v.validated_at IS NULL THEN
  IF ROW(v.pack_id,v.pack_version,v.container_schema_version,v.content_schema_version,v.content_kind,v.manifest_sha256,v.content_sha256,v.canonical_manifest_text,v.canonical_manifest_sha256,v.canonical_content_text,v.canonical_content_sha256,v.asset_set_text,v.asset_set_sha256,v.candidate_sha256,v.resource_count) IS DISTINCT FROM ROW(NULL::varchar,NULL::varchar,NULL::varchar,NULL::varchar,NULL::varchar,NULL::char,NULL::char,NULL::text,NULL::char,NULL::text,NULL::char,NULL::text,NULL::char,NULL::char,NULL::smallint) OR v.identity_kind<>'unclaimed' OR v.canonical_validation_id IS NOT NULL OR v.status IN ('validated','archiving','ready') THEN RETURN false; END IF;
 ELSE
  IF (v.pack_id ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$' AND v.pack_version ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$' AND v.container_schema_version ~ '^[!-~]{1,64}$' AND v.content_schema_version ~ '^[!-~]{1,64}$' AND ((current_policy AND v.container_schema_version='quizpack.v1' AND (v.content_schema_version IN ('quizpack-content.v1','quizpack-content.v2') OR (newest_policy AND v.content_schema_version='quizpack-content.v3')) AND v.content_kind IN ('synthetic','authored')) OR (NOT current_policy AND v.content_kind='synthetic'))
   AND v.manifest_sha256 ~ '^[0-9a-f]{64}$' AND v.content_sha256 ~ '^[0-9a-f]{64}$' AND v.candidate_sha256 ~ '^[0-9a-f]{64}$'
   AND v.canonical_manifest_sha256=qf.sha256_utf8(v.canonical_manifest_text) AND v.canonical_content_sha256=qf.sha256_utf8(v.canonical_content_text) AND v.asset_set_sha256=qf.sha256_utf8(v.asset_set_text)
   AND v.validated_at>=v.created_at AND v.resource_count BETWEEN 1 AND 64 AND v.identity_kind IN ('canonical','alias','conflict') AND v.status<>'validating') IS NOT TRUE THEN RETURN false; END IF;
  IF (v.identity_kind='alias') IS DISTINCT FROM (v.canonical_validation_id IS NOT NULL) THEN RETURN false; END IF;
  IF v.identity_kind='conflict' AND v.status<>'rejected' THEN RETURN false; END IF;
  man:=v.canonical_manifest_text::jsonb; content:=v.canonical_content_text::jsonb; aset:=v.asset_set_text::jsonb;
  IF qf.private_test_source_valid(content,v.asset_set_sha256::text,v.canonical_manifest_sha256::text) IS NOT TRUE THEN RETURN false; END IF;
  IF v.content_schema_version='quizpack-content.v3' AND qf.consumer_body_valid_v2(v.canonical_content_text,'content',2097152) IS NOT TRUE THEN RETURN false; END IF;
  IF (man->>'productId'=v.product_id AND (CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>>'{core,scoringDefinition,productId}' ELSE content#>>'{product,productId}' END)=v.product_id AND man->>'packId'=v.pack_id AND man->>'packVersion'=v.pack_version
    AND man->>'schemaVersion'=v.container_schema_version AND man->>'contentSchemaVersion'=v.content_schema_version AND content->>'schemaVersion'=v.content_schema_version AND (CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>>'{bindings,kind}' ELSE content->>'kind' END)=v.content_kind
    AND jsonb_typeof((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,resources}' ELSE content->'resources' END))='array' AND jsonb_typeof(aset)='object' AND (SELECT count(*) FROM jsonb_object_keys(aset))=3 AND aset->>'schemaVersion'='quizpack-candidate-asset-set.v1' AND aset->>'productId'=v.product_id AND jsonb_typeof(aset->'resources')='array') IS NOT TRUE THEN RETURN false; END IF;
  IF current_policy THEN
   component_version:=CASE v.content_schema_version WHEN 'quizpack-content.v2' THEN '2.0.0' ELSE '1.0.0' END;
   IF ((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>>'{bindings,componentVersion}' ELSE content->>'componentVersion' END)=component_version AND ((v.content_schema_version='quizpack-content.v3' AND (CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>>'{core,scoringDefinition,engine,id}' ELSE content#>>'{engine,id}' END)='archetype-l1') OR (v.content_schema_version<>'quizpack-content.v3' AND (CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>>'{core,scoringDefinition,engine,id}' ELSE content#>>'{engine,id}' END) IN ('dimensions','archetype')))
     AND (CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>>'{core,scoringDefinition,engine,version}' ELSE content#>>'{engine,version}' END)='1.0.0' AND man->'engine'=(CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{core,scoringDefinition,engine}' ELSE content->'engine' END)
     AND jsonb_typeof(man->'components')='array' AND jsonb_array_length(man->'components')=6
     AND jsonb_typeof((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,layouts}' ELSE content->'layouts' END))='object' AND (SELECT count(*) FROM jsonb_object_keys((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,layouts}' ELSE content->'layouts' END)))=6
     AND jsonb_typeof((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,reportTemplates}' ELSE content->'reportTemplates' END))='array' AND jsonb_array_length((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,reportTemplates}' ELSE content->'reportTemplates' END)) BETWEEN 1 AND 32) IS NOT TRUE THEN RETURN false; END IF;
   FOR state_name,component_id IN SELECT * FROM (VALUES ('cover','folio-cover'),('question','folio-question'),('resume','folio-resume'),('result','cabinet-result'),('report','folio-report'),('poster','folio-poster')) AS x(state,id) LOOP
    IF v.content_schema_version='quizpack-content.v3' THEN component_id:='composed-'||state_name; END IF;
    IF (((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>ARRAY['bindings','layouts',state_name,'component'] ELSE content#>ARRAY['layouts',state_name,'component'] END))=jsonb_build_object('id',component_id,'version',component_version,'propsSchemaVersion','1.0.0')
      AND (SELECT count(*) FROM jsonb_array_elements(man->'components') c WHERE c=jsonb_build_object('id',component_id,'version',component_version,'propsSchemaVersion','1.0.0'))=1) IS NOT TRUE THEN RETURN false; END IF;
   END LOOP;
   IF v.content_schema_version<>'quizpack-content.v3' AND EXISTS(SELECT 1 FROM jsonb_array_elements((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,reportTemplates}' ELSE content->'reportTemplates' END)) t WHERE (t->'component'=jsonb_build_object('id','folio-report','version',component_version,'propsSchemaVersion','1.0.0')) IS NOT TRUE) THEN RETURN false; END IF;
  END IF;
  IF jsonb_array_length(aset->'resources')<>v.resource_count OR jsonb_array_length((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,resources}' ELSE content->'resources' END))<>v.resource_count THEN RETURN false; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(aset->'resources') LOOP
   IF (jsonb_typeof(item)='object' AND (SELECT count(*) FROM jsonb_object_keys(item))=5 AND item->>'productId'=v.product_id AND item->>'resourceId' ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$' AND item->>'resourceVersion' ~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$' AND item->>'blobSha256' ~ '^[0-9a-f]{64}$' AND item->>'declarationSha256' ~ '^[0-9a-f]{64}$') IS NOT TRUE THEN RETURN false; END IF;
   key_text:=(item->>'productId')||'/'||(item->>'resourceId')||'/'||(item->>'resourceVersion');
   IF key_text=ANY(seen) OR (prior_id IS NOT NULL AND ((item->>'resourceId') COLLATE "C"<prior_id COLLATE "C" OR ((item->>'resourceId')=prior_id AND (item->>'resourceVersion') COLLATE "C"<=prior_version COLLATE "C"))) THEN RETURN false; END IF; seen:=array_append(seen,key_text); prior_id:=item->>'resourceId'; prior_version:=item->>'resourceVersion';
   SELECT value INTO declaration FROM jsonb_array_elements((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,resources}' ELSE content->'resources' END)) WHERE value->>'productId'=v.product_id AND value->>'id'=item->>'resourceId' AND value->>'version'=item->>'resourceVersion';
   IF (declaration->>'sha256'=item->>'blobSha256') IS NOT TRUE OR (SELECT count(*) FROM jsonb_array_elements((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN content#>'{bindings,resources}' ELSE content->'resources' END)) WHERE value->>'productId'=v.product_id AND value->>'id'=item->>'resourceId' AND value->>'version'=item->>'resourceVersion')<>1 THEN RETURN false; END IF;
  END LOOP;
  IF v.evidence_text IS NULL THEN RETURN false; END IF;
 END IF;
 IF v.evidence_text IS NOT NULL THEN
  evidence:=v.evidence_text::jsonb;
  FOR item IN SELECT value FROM jsonb_array_elements(evidence->'attempts') LOOP
   IF item#>>'{result,evidence,input,status}'='snapshotted' THEN
    IF (item#>>'{result,evidence,input,targetProductId}'=v.product_id AND item#>>'{result,evidence,input,archiveSha256}'=v.archive_sha256 AND item#>'{result,evidence,input,archiveBytes}'=to_jsonb(v.archive_bytes)) IS NOT TRUE THEN RETURN false; END IF;
   ELSIF (item#>>'{result,evidence,input,status}'='unavailable' AND item#>>'{result,outcome}'='interrupted' AND item#>>'{result,evidence,input,code}' IN ('INVALID_INPUT','INVALID_TARGET_PRODUCT')) IS NOT TRUE THEN RETURN false;
   END IF;
   IF item#>>'{result,evidence,identity,status}'='bound' THEN
    IF (item#>>'{result,evidence,identity,value,identitySha256}'=v.identity_sha256 AND (NOT current_policy OR item#>'{result,evidence,identity,value}'=ident)) IS NOT TRUE THEN RETURN false; END IF;
   ELSIF (item#>>'{result,evidence,identity,status}'='unavailable' AND item#>>'{result,outcome}'='interrupted' AND item#>>'{result,evidence,identity,code}' IN ('INVALID_CONTEXT','RUNTIME_IDENTITY_UNAVAILABLE')) IS NOT TRUE THEN RETURN false;
   END IF;
   -- Unavailable facts are truthful interrupted evidence, including historical attempts.
   -- A later accepted retry freezes a candidate without rewriting those earlier unavailable items.
   IF item#>>'{result,outcome}' IN ('accepted','rejected') AND (item#>>'{result,evidence,input,status}'='snapshotted' AND item#>>'{result,evidence,identity,status}'='bound') IS NOT TRUE THEN RETURN false; END IF;
   IF current_policy AND item#>>'{result,evidence,report,status}'='sealed' THEN
    IF (item#>>'{result,evidence,identity,status}'='bound'
     AND item#>'{result,evidence,identity,value}'=ident
     AND item#>>'{result,evidence,report,value,schemaVersion}'=ident->>'reportSchemaVersion'
     AND item#>>'{result,evidence,report,value,validatorVersion}'=ident->>'validatorVersion'
     AND item#>>'{result,evidence,report,value,policyId}'=ident->>'policyId'
     AND item#>>'{result,evidence,report,value,compatibilityPolicyHash}'=ident->>'compatibilityPolicyHash'
     AND item#>>'{result,evidence,report,value,effectiveLimitsHash}'=ident->>'effectiveLimitsHash') IS NOT TRUE THEN RETURN false; END IF;
   END IF;
   IF item#>>'{result,outcome}'='accepted' THEN
    accepted:=item;
    IF (item#>>'{result,evidence,report,status}'='sealed' AND item#>'{result,evidence,report,value,candidateValid}'='true'::jsonb AND item#>>'{result,evidence,policy,status}'='passed'
      AND item#>>'{result,evidence,report,value,manifestSha256}'=v.manifest_sha256 AND item#>>'{result,evidence,report,value,contentSha256}'=v.content_sha256) IS NOT TRUE THEN RETURN false; END IF;
   END IF;
  END LOOP;
  IF v.validated_at IS NOT NULL AND accepted IS NULL THEN RETURN false; END IF;
 END IF;
 IF v.status='ready' THEN
  RETURN (v.ready_at>=v.validated_at AND v.identity_kind IN ('canonical','alias') AND v.storage_condition='clean' AND v.reserved_bytes=0 AND v.lease_until IS NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v.attempts_text::jsonb) a WHERE a->>'disposition'<>'released' OR a->>'mediaStop'='unconfirmed')) IS TRUE;
 END IF;
 IF v.ready_at IS NOT NULL THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION qf.protect_product_asset() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE v qf.quizpack_validation; item jsonb; declaration jsonb;
BEGIN
 SELECT * INTO v FROM qf.quizpack_validation WHERE product_id=NEW.product_id AND id=NEW.source_validation_id;
 IF v.validated_at IS NOT NULL AND qf.private_test_source_valid(v.canonical_content_text::jsonb,v.asset_set_sha256::text,v.canonical_manifest_sha256::text) IS NOT TRUE THEN RAISE EXCEPTION 'PRIVATE_TEST_SCOPE' USING ERRCODE='23514'; END IF;
 IF v.validated_at IS NULL THEN RAISE EXCEPTION 'ASSET_SOURCE' USING ERRCODE='23514'; END IF;
 SELECT value INTO item FROM jsonb_array_elements(v.asset_set_text::jsonb->'resources') WHERE value->>'productId'=NEW.product_id AND value->>'resourceId'=NEW.resource_id AND value->>'resourceVersion'=NEW.resource_version;
 SELECT value INTO declaration FROM jsonb_array_elements((CASE WHEN v.content_schema_version='quizpack-content.v3' THEN v.canonical_content_text::jsonb#>'{bindings,resources}' ELSE v.canonical_content_text::jsonb->'resources' END)) WHERE value->>'productId'=NEW.product_id AND value->>'id'=NEW.resource_id AND value->>'version'=NEW.resource_version;
 IF (item->>'blobSha256'=NEW.blob_sha256 AND item->>'declarationSha256'=NEW.declaration_sha256 AND declaration=NEW.declaration_text::jsonb) IS NOT TRUE THEN RAISE EXCEPTION 'ASSET_SET' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION qf.protect_consumer_report() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE p qf.internal_play_version; s qf.consumer_session; body jsonb; expected jsonb; is_v2 boolean; source jsonb; score jsonb; display jsonb; normalized jsonb; chosen_character jsonb; expected_body jsonb; k qf.access_key;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_CONSUMER_REPORT' USING ERRCODE='23514'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'CONSUMER_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 PERFORM 1 FROM qf.access_key WHERE id=NEW.key_id FOR UPDATE;
 SELECT * INTO s FROM qf.consumer_session WHERE id=NEW.session_id AND key_id=NEW.key_id FOR UPDATE;
 SELECT * INTO p FROM qf.internal_play_version WHERE id=NEW.play_version_id AND product_id=NEW.product_id AND snapshot_sha256=NEW.play_snapshot_sha256;
 IF s.id IS NULL OR p.id IS NULL THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 expected:=jsonb_build_object('schemaVersion','quizforge.internal-play-receipt.v1','id',p.id,'slot',p.slot,'binding',p.binding_text::jsonb,'bindingSha256',p.binding_sha256::text,'snapshotSha256',p.snapshot_sha256::text,'createdBy',p.created_by,'createdAt',qf.consumer_moment(p.created_at),'purpose','internal-test','publicationApproved',false);
 body:=NEW.snapshot_text::jsonb;
 IF body->'play' IS DISTINCT FROM jsonb_build_object('play',expected,'snapshot',p.snapshot_text::jsonb) OR body->'answers' IS DISTINCT FROM s.answers_text::jsonb->'answers' OR body->'progress' IS DISTINCT FROM s.progress_text::jsonb->'progress' THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 is_v2:=qf.consumer_protocol_v2(NEW.product_id,NEW.play_version_id,NEW.play_snapshot_sha256::text);
 IF is_v2 IS NULL THEN RAISE EXCEPTION 'CONSUMER_PROTOCOL_MISMATCH' USING ERRCODE='23514'; END IF;
 IF NOT is_v2 THEN
  IF NEW.matching_context_sha256 IS NOT NULL OR s.matching_context_text IS NOT NULL OR s.matching_context_sha256 IS NOT NULL THEN RAISE EXCEPTION 'CONSUMER_PROTOCOL_MISMATCH' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF (NEW.matching_context_sha256 IS NOT NULL AND s.matching_context_text IS NOT NULL AND s.matching_context_sha256 IS NOT NULL AND NEW.matching_context_sha256=s.matching_context_sha256 AND s.matching_context_text<>'null' AND qf.consumer_canonical(body->'matchingContext')=s.matching_context_text) IS NOT TRUE THEN RAISE EXCEPTION 'CONSUMER_REPORT_CONTEXT_MISMATCH' USING ERRCODE='23514'; END IF;
 SELECT * INTO k FROM qf.access_key WHERE id=NEW.key_id;
 IF k.revoked_at IS NOT NULL OR k.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CONSUMER_REPORT_DEADLINE' USING ERRCODE='23514'; END IF;
 SELECT d.canonical_content_text::jsonb INTO source FROM qf.product_version v JOIN qf.draft_revision d ON(d.product_id,d.draft_id,d.revision)=(v.product_id,v.draft_id,v.revision) WHERE (v.id,v.product_id,v.snapshot_sha256)=(p.parent_version_id,p.product_id,p.parent_snapshot_sha256);
 IF (source->>'schemaVersion'='quizpack-content.v3' AND qf.sha256_utf8(qf.consumer_canonical(source))=p.snapshot_text::jsonb#>>'{parentSnapshot,target,canonicalContentSha256}') IS NOT TRUE THEN RAISE EXCEPTION 'CONSUMER_REPORT_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 IF qf.private_test_source_valid(source,p.snapshot_text::jsonb#>>'{parentSnapshot,target,assetSetSha256}',p.snapshot_text::jsonb#>>'{parentSnapshot,target,canonicalManifestSha256}') IS NOT TRUE THEN RAISE EXCEPTION 'PRIVATE_TEST_SCOPE' USING ERRCODE='23514'; END IF;
 score:=body#>'{score,score}';display:=body#>'{view,display}';
 SELECT jsonb_agg(a ORDER BY n) INTO normalized FROM jsonb_array_elements(source#>'{core,questions}') WITH ORDINALITY question(q,n) JOIN LATERAL jsonb_array_elements(s.answers_text::jsonb->'answers') a ON a->>'questionId'=q#>>'{ref,id}';
 IF (jsonb_array_length(normalized)=jsonb_array_length(source#>'{core,questions}') AND normalized=score->'normalizedAnswers'
  AND score->>'logicHash'=qf.sha256_utf8(E'quizforge:quiz-logic.v2\n'||qf.consumer_canonical(source#>'{core,scoringDefinition}'))
  AND body#>'{matchingContext,policyRef}'=source#>'{core,scoringDefinition,matchingPolicy,ref}'
  AND EXISTS(SELECT 1 FROM jsonb_array_elements(source#>'{core,scoringDefinition,profiles}') profile WHERE profile->'resultRef'=score#>'{decision,selectedResultRef}' AND (body#>>'{matchingContext,preference}'='any' OR body#>>'{matchingContext,preference}'=profile->>'sex') AND profile->'kind' IN (SELECT value FROM jsonb_array_elements(source#>'{core,scoringDefinition,matchingPolicy,allowedKinds}')))) IS NOT TRUE THEN RAISE EXCEPTION 'CONSUMER_REPORT_INPUT_MISMATCH' USING ERRCODE='23514'; END IF;
 expected_body:=qf.composed_body_v1(source,body->'score');
 IF expected_body IS NULL OR display->'body' IS DISTINCT FROM expected_body THEN RAISE EXCEPTION 'CONSUMER_REPORT_BODY_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 SELECT c INTO chosen_character FROM jsonb_array_elements(source#>'{bindings,slots,characters}') c WHERE c->'resultRef'=score#>'{decision,selectedResultRef}';
 IF chosen_character IS NULL OR display->'slots' IS DISTINCT FROM jsonb_build_object('neutral',source#>'{bindings,slots,neutral}','character',chosen_character) OR display->'assets' IS DISTINCT FROM qf.composed_assets_v1(source,chosen_character) THEN RAISE EXCEPTION 'CONSUMER_REPORT_RESOURCE_SCOPE' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION qf.protect_internal_reference() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE r qf.draft_revision; v qf.quizpack_validation; review qf.draft_review; s jsonb; head integer; archived timestamptz;
BEGIN
 IF TG_TABLE_NAME='draft_review' THEN IF NEW.facts_text::jsonb#>>'{approval,kind}'='private-test-only' AND qf.private_test_database_valid() IS NOT TRUE THEN RAISE EXCEPTION 'PRIVATE_TEST_SCOPE' USING ERRCODE='23514'; END IF; END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'IMMUTABLE_INTERNAL_REFERENCE' USING ERRCODE='23514'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(72461,2) THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_MAINTENANCE_BUSY' USING ERRCODE='55P03'; END IF;
 SELECT archived_at INTO archived FROM qf.product WHERE id=NEW.product_id FOR UPDATE;
 IF NOT FOUND OR archived IS NOT NULL THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_PRODUCT_INACTIVE' USING ERRCODE='23514'; END IF;
 SELECT current_revision INTO head FROM qf.product_draft WHERE product_id=NEW.product_id AND id=NEW.draft_id;
 IF head IS DISTINCT FROM NEW.revision THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_HEAD_CHANGED' USING ERRCODE='23514'; END IF;
 SELECT * INTO r FROM qf.draft_revision WHERE product_id=NEW.product_id AND draft_id=NEW.draft_id AND revision=NEW.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'INTERNAL_REFERENCE_SOURCE_MISSING' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='draft_review' THEN
  IF (NEW.source_import_id,NEW.source_validation_id,NEW.source_validation_state_revision) IS DISTINCT FROM (r.source_import_id,r.source_validation_id,r.source_validation_state_revision) THEN RAISE EXCEPTION 'INTERNAL_REVIEW_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT * INTO review FROM qf.draft_review WHERE product_id=NEW.product_id AND id=NEW.review_id;
  SELECT * INTO v FROM qf.quizpack_validation WHERE product_id=r.product_id AND import_id=r.source_import_id AND id=r.source_validation_id;
  s:=NEW.snapshot_text::jsonb;
  IF review.id IS NULL OR v.id IS NULL OR s->'baseline' IS DISTINCT FROM review.facts_text::jsonb->'baseline'
   OR (s->>'packId',s->>'packVersion',s->>'contentSchemaVersion',s->>'contentKind') IS DISTINCT FROM (r.pack_id::text,r.pack_version::text,r.content_schema_version::text,r.content_kind::text)
   OR s->'versions' IS DISTINCT FROM jsonb_build_object('contentVersion',r.content_version,'visualVersion',r.visual_version,'reportVersion',r.report_version,'resourceVersion',r.resource_version,'componentVersion',r.component_version,'engine',jsonb_build_object('id',r.engine_id,'version',r.engine_version))
   OR s->'validation' IS DISTINCT FROM jsonb_build_object('sourceImportId',r.source_import_id,'sourceValidationId',r.source_validation_id,'sourceValidationStateRevision',r.source_validation_state_revision,'archiveSha256',v.archive_sha256::text,'candidateSha256',r.candidate_sha256::text,'identitySha256',v.identity_sha256::text,'validatorBundleSha256',v.identity_text::jsonb->>'validatorBundleSha256','archivePolicyVersion',v.archive_policy_version,'archivePolicySha256',v.archive_policy_sha256::text,'evidenceSha256',v.evidence_sha256::text)
  THEN RAISE EXCEPTION 'INTERNAL_VERSION_SOURCE_MISMATCH' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION qf.consumer_report_valid(r qf.quiz_report) RETURNS boolean LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog AS $$
DECLARE private_source jsonb; is_v2 boolean; b jsonb; s jsonb; v jsonb; d jsonb; score jsonb; ref jsonb; play jsonb; parent jsonb; context_sha text;
BEGIN
 is_v2:=qf.consumer_protocol_v2(r.product_id,r.play_version_id,r.play_snapshot_sha256::text);
 IF is_v2 IS NULL THEN RETURN false; END IF;
 IF NOT is_v2 THEN RETURN (r.matching_context_sha256 IS NULL AND qf.consumer_report_valid_v1(r)) IS TRUE; END IF;
 IF (r.matching_context_sha256 IS NOT NULL AND r.matching_context_sha256 ~ '^[a-f0-9]{64}$' AND qf.consumer_body_valid_v2(r.binding_text,'complete',4096) AND qf.consumer_body_valid_v2(r.snapshot_text,'report',524288)) IS NOT TRUE THEN RETURN false; END IF;
 b:=r.binding_text::jsonb;s:=r.snapshot_text::jsonb;v:=s->'view';d:=v->'display';score:=s#>'{score,score}';play:=s#>'{play,snapshot}';parent:=play->'parentSnapshot';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(d->'assets') a WHERE a->>'approval'='private-test-only') THEN
  SELECT dr.canonical_content_text::jsonb INTO private_source FROM qf.product_version pv JOIN qf.draft_revision dr ON(dr.product_id,dr.draft_id,dr.revision)=(pv.product_id,pv.draft_id,pv.revision) WHERE pv.id=(play#>>'{parent,versionId}')::uuid AND pv.product_id=r.product_id;
  IF private_source IS NULL OR qf.private_test_source_valid(private_source,parent#>>'{target,assetSetSha256}',parent#>>'{target,canonicalManifestSha256}') IS NOT TRUE THEN RETURN false; END IF;
 END IF;
 ref:=jsonb_build_object('productId',r.product_id,'playVersionId',r.play_version_id,'playSnapshotSha256',r.play_snapshot_sha256::text,'keyId',r.key_id,'sessionId',r.session_id);
 context_sha:=qf.sha256_utf8(E'quizforge:quiz-matching-context.v1\n'||qf.consumer_canonical(s->'matchingContext'));
 RETURN (r.binding_sha256::text=qf.sha256_utf8(r.binding_text) AND r.snapshot_sha256::text=qf.sha256_utf8(r.snapshot_text) AND r.display_sha256::text=qf.sha256_utf8(qf.consumer_canonical(v)) AND qf.consumer_moment(r.completed_at) IS NOT NULL
 AND b=jsonb_build_object('schemaVersion','quizforge.consumer-complete.v2','session',ref,'expectedStateRevision',r.state_revision,'consumerStateAnswersSha256',r.consumer_state_answers_sha256::text,'progressSha256',r.progress_sha256::text,'matchingContextSha256',r.matching_context_sha256::text,'completionKey',r.completion_key)
 AND s->'binding'=b AND v->'session'=ref AND v->>'reportId'=r.id::text AND v->>'completedAt'=qf.consumer_moment(r.completed_at) AND v->>'completionBindingSha256'=r.binding_sha256::text
 AND play->>'schemaVersion'='quizforge.internal-play-snapshot.v2' AND parent->>'schemaVersion'='quizforge.internal-version-snapshot.v2'
 AND v->'parent'=play->'parent' AND v->'renderer'=play->'renderer' AND v->'font'=parent->'font' AND v->'mapping'=play->'mapping' AND v->'mappingSha256'=play->'mappingSha256'
 AND jsonb_build_object('presentationMode',d->'presentationMode','exports',d->'exports')=play->'presentation'
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-answers.v1','answers',s->'answers')))=r.consumer_state_answers_sha256::text
 AND qf.sha256_utf8(qf.consumer_canonical(jsonb_build_object('schemaVersion','quizforge.consumer-state-progress.v1','progress',s->'progress')))=r.progress_sha256::text
 AND s->'matchingContext'<>'null'::jsonb AND s->'matchingContext'=score->'matchingContext' AND context_sha=r.matching_context_sha256::text AND context_sha=score->>'matchingContextSha256' AND context_sha=d->>'matchingContextSha256'
 AND qf.sha256_utf8(E'quizforge:quiz-answers.v2\n'||qf.consumer_canonical(score->'normalizedAnswers'))=score->>'answersHash'
 AND qf.sha256_utf8(E'quizforge:quiz-input.v2\n'||qf.consumer_canonical(jsonb_build_object('schemaVersion','quiz-scoring-input.v2','answers',score->'normalizedAnswers','matchingContext',s->'matchingContext')))=score->>'inputHash'
 AND score->'engine'=parent#>'{versions,engine}' AND score->>'logicHash'=parent->>'logicHash' AND score->>'productId'=r.product_id AND score->'contentVersion'=parent#>'{versions,contentVersion}'
 AND s#>'{score,canonicalContentSha256}'=parent#>'{target,canonicalContentSha256}' AND s#>'{score,reportVersion}'=parent#>'{versions,reportVersion}'
 AND d->'canonicalContentSha256'=s#>'{score,canonicalContentSha256}' AND d->'contentVersion'=score->'contentVersion' AND d->'reportVersion'=s#>'{score,reportVersion}' AND d->'logicHash'=score->'logicHash' AND d->'answersHash'=score->'answersHash' AND d->'inputHash'=score->'inputHash'
 AND score#>'{decision,selectedResultRef}'=d->'selectedResultRef' AND s#>'{score,reportTemplateRef}'=d->'reportTemplateRef'
 AND d->>'bodySha256'=qf.sha256_utf8(qf.consumer_canonical(d->'body'))) IS TRUE;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
REVOKE ALL ON FUNCTION qf.private_test_database_valid(),qf.private_test_structure_valid(jsonb),qf.private_test_source_valid(jsonb,text,text) FROM PUBLIC;
DO $$ BEGIN EXECUTE format('GRANT EXECUTE ON FUNCTION qf.private_test_database_valid(),qf.private_test_structure_valid(jsonb),qf.private_test_source_valid(jsonb,text,text) TO %I',replace(current_user,'qf_owner_','qf_app_')); END $$;
DO $$ DECLARE v qf.quizpack_validation; r qf.quiz_report; p qf.product_version; a qf.draft_review; BEGIN FOR v IN SELECT * FROM qf.quizpack_validation LOOP IF qf.validation_shape_valid(v) IS NOT TRUE THEN RAISE EXCEPTION 'PRIVATE_TEST_EXISTING_VALIDATION'; END IF; END LOOP; FOR a IN SELECT * FROM qf.draft_review LOOP IF qf.internal_review_valid(a) IS NOT TRUE THEN RAISE EXCEPTION 'PRIVATE_TEST_EXISTING_REVIEW'; END IF; END LOOP; FOR p IN SELECT * FROM qf.product_version LOOP IF qf.internal_version_valid(p) IS NOT TRUE THEN RAISE EXCEPTION 'PRIVATE_TEST_EXISTING_VERSION'; END IF; END LOOP; FOR r IN SELECT * FROM qf.quiz_report LOOP IF qf.consumer_report_valid(r) IS NOT TRUE THEN RAISE EXCEPTION 'PRIVATE_TEST_EXISTING_REPORT'; END IF; END LOOP; END $$;
